from record import source as S, edge as E, replace as R, record as P

p='t_m_devine';s='tq233_devine_slavery_extended2011';h='tq233_devine_wormald2012'
P(p,
'A historian of Scottish society, economy and diaspora whose slavery research places national history within Atlantic relationships. In “Did Slavery Make Scotia Great?” Devine returns to the controversy opened by Eric Williams while distinguishing profits from direct slave trading from the wider effects of plantation economies. The Scottish case, he argues, cannot be excluded merely because relatively few slave voyages departed from Scottish ports. His argument also criticizes the separation of Scottish research from British and international debates. In their jointly authored Handbook introduction, Devine and Jenny Wormald call for comparative work and internationalization rather than an insular national narrative. Morton and Griffiths nonetheless question the nation as the automatic container of historical synthesis, explicitly discussing The Scottish Nation. These perspectives retain both the national synthesis and the question of how its frame relates to movement, empire and social differentiation.',
'Primary 2011 article selected pp. 40–44 read, extending the earlier opening/trade scope; estimates and Williams’s originals not independently verified. Devine/Wormald’s jointly authored 2012 introduction selected pp. 14–15 read. Morton/Griffiths selected pp. 49–51 read, not entire article. Coauthors receive equal credit; their survey’s criticism is not reassigned to Devine. Complete selected books unread.',
sources=[S(s,'T. M. Devine, “Did Slavery Make Scotia Great?”, Britain and the World 4:1 (2011): 40–64, extended selected reading.','https://www.pure.ed.ac.uk/ws/portalfiles/portal/8206494/Did_slavery_make_Scotia_great.pdf','Selected printed pp. 40–44 read: Williams debate, broader plantation economy, neglect of Scotland and direct-voyage distinction. Original cited texts and estimates not independently checked; remainder not claimed read.'),S(h,'T. M. Devine and Jenny Wormald, “Introduction: The Study of Modern Scottish History,” Oxford Handbook of Modern Scottish History (2012): selected pp. 14–15.','https://api.pageplace.de/preview/DT0400.9780191624322_A24389997/preview-9780191624322_A24389997.pdf','Authorized publisher preview; selected joint introduction pp. 14–15 read, calling for internationalization, comparison and emerging fields. Not a complete introduction or handbook reading; all joint credit retained.')],
edges=[E(p,'williams','eric_williams',p,'Devine reopens Williams’s slavery-and-development question through Scotland and a wider plantation-economy frame.',s,'Primary pp. 40–42, an extended historiographical discussion with competing interpretations. Specific question/resource, not blanket adoption of every Williams thesis or first personal reading.')],
replacements=[R(p,1,p,'atlantic','Reconsiders Scotland’s development through the wider slave-based Atlantic economy rather than direct slaving voyages alone.',s,'Primary pp. 40–44. Scope of inquiry, not certification of every financial estimate.',batch=2)],
reads=[dict(source_id=s,locator='pp. 40–44'),dict(source_id=h,locator='Joint introduction pp. 14–15'),dict(source_id='tc233_scotland_frame',locator='Extended selected pp. 49–51')],holds=['Full books and original Williams/critics texts unread. Do not turn national synthesis into nationalist allegiance.'])

p='richard_j_evans';s='evans'
P(p,
'A historian of modern Germany who also examines the practice and public responsibilities of historical inquiry. In Defence of History defends evidence while refusing to make the profession immune to outside criticism. Its introduction accepts White’s objection to historians claiming sole authority to explain their own work and distinguishes this from accepting every postmodernist argument. Evans criticizes the determinism of declaring postmodernity an unavoidable fate and uses Carr and Elton as valuable but insufficient guides to later debates. His accounts of disease and German society connect institutions with inequality; his public source-criticism work in the Irving trial is a distinct intervention. These projects supply a historically situated defence of inquiry, not a neutral census of all narrative theory or proof that historians can recover the past without interpretive choices.',
'1997 acknowledgments and introduction I–III, displayed in licensed later preview, re-read for specified passages and notes 36–45. Earlier chapter/later-section limits remain: no full book or afterword reading. Wolfson institutional accounts, not original Hamburg book or trial evidence, support those additional contexts. White’s and Joyce’s original texts not freshly read; Evans’s polemical assessments remain attributed.',
existing=[s],
edges=[E(p,'white','white',p,'Evans accepts White’s argument that historians can learn from external inquiry into how historical knowledge is made.',s,'Primary introduction III, paragraph beginning White is surely correct and n38. Specific agreement with White’s response to Marwick, not acceptance of his entire narrative theory.'),E(p,'joyce',p,'patrick_joyce','Evans challenges the claim that historians must accept postmodernity as an irresistible condition.',s,'Introduction III, Joyce quotation and nn43–45, followed by criticism of apodictic inevitability. Joyce is named with Jenkins; no whole-corpus verdict.',kind='critique'),E(p,'cannadine','david_cannadine',p,'Evans credits Cannadine’s criticism of drafts during the development of In Defence of History.',s,'March 1997 acknowledgments, explicit thanks for criticism during rewritings. Bounded scholarly contribution, no invented detail about which arguments changed.')],
reads=[dict(source_id=s,locator='Fresh licensed-preview introduction III and nn36–45; March 1997 acknowledgments')],holds=['Original White/Joyce texts, court evidence and full books unread. No SSK/Latour relationship inferred from tangential postmodernism discussion.'])

p='e_h_carr';s='evans';r='carr_facts_primary'
P(p,
'A historian of international relations and Soviet Russia whose methodological lectures made the relationship between evidence and interpretation a central problem. The checked first chapter of What Is History? treats historical facts as selected and organized through questions, while describing research and interpretation as an iterative interaction rather than licensing equally valid accounts of anything. The historian’s present matters, but so do the materials that resist interpretation. In his later introduction, Evans values Carr’s challenge to passive fact-collection while questioning whether a Carr-versus-Elton framework adequately addresses subsequent theoretical disputes. That later reception is separate from Carr’s own 1961 intervention. The Twenty Years’ Crisis and The Bolshevik Revolution mark other projects; their specific political arguments remain outside this packet’s reading rather than being inferred from titles.',
'Existing complete first-chapter reading retained with its defective transcription, absent original pagination and uncollated notes; no fresh full-book reading. Evans’s 1997 introduction I, nn1–5, freshly read as a specific later appraisal. Other Carr books and later What Is History? chapters unread. Political-history affiliation remains held for relevant passage evidence; later reception does not make Carr a self-described postmodernist.',
existing=[s,r],
edges=[E(p,'evans','richard_j_evans',p,'Evans values Carr’s challenge to fact-collection while questioning the adequacy of his introductory framework for later theoretical debate.',s,'Primary Evans introduction I, paragraphs beginning Carr was a practising historian and Nothing has outdated, plus nn1–5. A qualified 1997 reception, not Carr’s own self-description.',kind='critique'),E(p,'laterdebate',p,'truthdebate','Carr’s account of facts and interpretation becomes a reference point in later disputes about historical truth and postmodernism.',s,'Evans introduction I explicitly sets Carr/Elton against later theoretical questions. Dated later use of Carr, not an anachronistic claim that his 1961 lectures addressed every later theory.')],
reads=[dict(source_id=r,locator='Existing complete chapter-one reading; original transcription limits unchanged',fresh=False),dict(source_id=s,locator='Fresh Evans introduction I and nn1–5')],holds=['Do not infer a new Ranke, Croce or Collingwood arrow solely from remembered arguments or an uncollated note. Other book arguments unread.'])

p='t_c_smout';s='tq233_smout_environment2012'
P(p,
'A historian of Scottish society and environments whose work joins changing material constraints to changing perceptions of nature. In “Land and Sea,” Smout explicitly uses Wrigley’s account of energy capture and the transition from organic to fossil-fuel economies. The chapter also identifies Cronon’s city-and-hinterland history as a model for work still needed on Scottish cities. These are particular resources, not an assertion that every Scottish development follows an English or American pattern. His earlier green-consciousness lecture questions a simple story in which appreciation of Highland landscapes was imported into a previously indifferent society. The social syntheses remain important to the entry, but their national frame is also questioned in Morton and Griffiths’s historiographical discussion. Environmental change, social organization and historical meaning thus intersect without turning landscape into a timeless explanation of national character.',
'Newly read primary 2012 chapter selected pp. 19–21 and 26–28 in authorized publisher preview, including nn1 and26. Earlier printed lecture pp. 237–238 and institutional/named-reader scopes retained; Morton/Griffiths extended opening pp. 49–51 read. No full chapter or book reading. Wrigley/Cronon originals and quantitative climate/health estimates not independently checked; source comparisons are bounded research resources.',
sources=[S(s,'T. C. Smout, “Land and Sea: The Environment,” Oxford Handbook of Modern Scottish History (2012), pp. 19–38: selected passages.','https://api.pageplace.de/preview/DT0400.9780191624322_A24389997/preview-9780191624322_A24389997.pdf','Authorized preview; selected printed pp. 19–21 and 26–28, nn1 and26 read. Explicit Wrigley resource and Cronon research model; no independent quantitative/environmental verification, full chapter or cited-original reading.')],
edges=[E(p,'wrigley','e_a_wrigley',p,'Smout uses Wrigley’s account of energy capture to frame transitions in Scottish economic and environmental history.',s,'Primary p. 19/n1 and p. 20, explicit named use with body argument. Original Wrigley articles and numerical estimates not independently verified.'),E(p,'cronon','william_cronon',p,'Smout identifies Cronon’s city-and-hinterland study as a model for an environmental history of Scottish cities still to be written.',s,'Primary pp. 27–28/n26, names Nature’s Metropolis. Specific research model and gap, not wholesale transfer of Chicago findings.')],
replacements=[R(p,1,p,'environment','Connects material energy constraints, social organization and changing understandings of nature.',['tc233_smout_lecture',s],'Primary lecture pp. 237–238 and chapter pp. 19–21,26–28. Distinct works/scales retained; no timeless national landscape.',batch=2)],
reads=[dict(source_id=s,locator='Selected pp. 19–21,26–28/nn1,26'),dict(source_id='tc233_scotland_frame',locator='Extended opening pp. 49–51')],holds=['Neither the energy framework nor the research-model reference establishes exclusive influence. Full monographs and source originals unread.'])
